<script>
/* === SLIDE PRESENTATION CONTROLLER === */
class SlidePresentation {{
  constructor() {{
    this.slides = Array.from(document.querySelectorAll('.slide'));
    this.totalSlides = this.slides.length;
    this.currentSlide = 0;
    this.isScrolling = false;

    this.progressBar = document.getElementById('progressBar');
    this.navDotsContainer = document.getElementById('navDots');

    this.setupIntersectionObserver();
    this.setupKeyboardNav();
    this.setupTouchNav();
    this.setupMouseWheel();
    this.setupNavDots();
    this.updateProgress(0);
  }}

  setupIntersectionObserver() {{
    const observer = new IntersectionObserver((entries) => {{
      entries.forEach(entry => {{
        if (entry.isIntersecting) {{
          entry.target.classList.add('visible');
          const idx = this.slides.indexOf(entry.target);
          if (idx !== -1) {{
            this.currentSlide = idx;
            this.updateProgress(idx);
            this.updateNavDots(idx);
          }}
        }}
      }});
    }}, {{ threshold: 0.5 }});

    this.slides.forEach(slide => observer.observe(slide));
  }}

  scrollToSlide(idx) {{
    if (idx < 0 || idx >= this.totalSlides) return;
    this.slides[idx].scrollIntoView({{ behavior: 'smooth', block: 'start' }});
  }}

  setupKeyboardNav() {{
    document.addEventListener('keydown', (e) => {{
      switch (e.key) {{
        case 'ArrowDown': case 'ArrowRight': case ' ':
          e.preventDefault();
          this.scrollToSlide(this.currentSlide + 1);
          break;
        case 'ArrowUp': case 'ArrowLeft':
          e.preventDefault();
          this.scrollToSlide(this.currentSlide - 1);
          break;
        case 'Home':
          e.preventDefault();
          this.scrollToSlide(0);
          break;
        case 'End':
          e.preventDefault();
          this.scrollToSlide(this.totalSlides - 1);
          break;
      }}
    }});
  }}

  setupTouchNav() {{
    let touchStartY = 0;
    document.addEventListener('touchstart', (e) => {{
      touchStartY = e.touches[0].clientY;
    }}, {{ passive: true }});
    document.addEventListener('touchend', (e) => {{
      const deltaY = touchStartY - e.changedTouches[0].clientY;
      if (Math.abs(deltaY) > 50) {{
        this.scrollToSlide(deltaY > 0 ? this.currentSlide + 1 : this.currentSlide - 1);
      }}
    }}, {{ passive: true }});
  }}

  setupMouseWheel() {{
    let lastWheel = 0;
    document.addEventListener('wheel', (e) => {{
      e.preventDefault();
      const now = Date.now();
      if (now - lastWheel < 800) return;
      lastWheel = now;
      this.scrollToSlide(e.deltaY > 0 ? this.currentSlide + 1 : this.currentSlide - 1);
    }}, {{ passive: false }});
  }}

  setupNavDots() {{
    this.slides.forEach((_, idx) => {{
      const btn = document.createElement('button');
      btn.className = 'nav-dot' + (idx === 0 ? ' active' : '');
      btn.setAttribute('aria-label', `Go to slide ${{idx + 1}}`);
      btn.addEventListener('click', () => this.scrollToSlide(idx));
      this.navDotsContainer.appendChild(btn);
    }});
  }}

  updateNavDots(activeIdx) {{
    const dots = this.navDotsContainer.querySelectorAll('.nav-dot');
    dots.forEach((dot, idx) => {{
      dot.classList.toggle('active', idx === activeIdx);
    }});
  }}

  updateProgress(slideIdx) {{
    const pct = this.totalSlides > 1
      ? (slideIdx / (this.totalSlides - 1)) * 100
      : 100;
    this.progressBar.style.width = pct + '%';
  }}
}}

new SlidePresentation();
</script>
