<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Syne:wght@600;700;800&family=IBM+Plex+Sans:wght@300;400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap">
<style>

/* === RESET === */
*, *::before, *::after {{ margin: 0; padding: 0; box-sizing: border-box; }}

/* === THEME VARIABLES === */
:root {{
  --bg:         #06101f;
  --bg2:        #091526;
  --bg3:        #0d1e35;
  --blue:       #3b9ddd;
  --blue-dim:   rgba(59,157,221,0.15);
  --blue-glow:  rgba(59,157,221,0.35);
  --amber:      #f5a623;
  --amber-dim:  rgba(245,166,35,0.15);
  --green:      #2ecc71;
  --red:        #e74c3c;
  --text:       #dce8f5;
  --text2:      #8aa4be;
  --text3:      #4d6a85;
  --border:     rgba(59,157,221,0.2);
  --border2:    rgba(59,157,221,0.1);
  --card:       rgba(255,255,255,0.04);
  --card-hover: rgba(255,255,255,0.07);

  --font-d: 'Syne', sans-serif;
  --font-b: 'IBM Plex Sans', sans-serif;
  --font-m: 'IBM Plex Mono', monospace;

  --title-size:    clamp(1.6rem, 4.5vw, 3.8rem);
  --h2-size:       clamp(1.2rem, 2.8vw, 2.2rem);
  --h3-size:       clamp(0.95rem, 1.8vw, 1.4rem);
  --body-size:     clamp(0.72rem, 1.2vw, 1rem);
  --small-size:    clamp(0.6rem, 0.9vw, 0.8rem);
  --mono-size:     clamp(0.65rem, 1.1vw, 0.9rem);

  --slide-padding: clamp(1.5rem, 4vw, 4rem);
  --content-gap:   clamp(0.6rem, 1.5vw, 1.5rem);
  --el-gap:        clamp(0.3rem, 0.8vw, 0.8rem);

  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --dur: 0.65s;
}}

/* === VIEWPORT BASE (mandatory) === */
html, body {{ height: 100%; overflow-x: hidden; }}
html {{ scroll-snap-type: y mandatory; scroll-behavior: smooth; }}

.slide {{
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  overflow: hidden;
  scroll-snap-align: start;
  display: flex;
  flex-direction: column;
  position: relative;
  background: var(--bg);
  font-family: var(--font-b);
  color: var(--text);
}}

.slide-content {{
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-height: 100%;
  overflow: hidden;
  padding: var(--slide-padding);
}}

.card, .container, .content-box {{
  max-width: min(90vw, 1000px);
  max-height: min(80vh, 700px);
}}

img, .image-container {{
  max-width: 100%;
  max-height: min(50vh, 400px);
  object-fit: contain;
}}

@media (max-height: 700px) {{
  :root {{
    --slide-padding: clamp(0.75rem, 3vw, 2rem);
    --content-gap: clamp(0.4rem, 1.2vw, 0.9rem);
    --title-size: clamp(1.2rem, 4vw, 2.4rem);
    --h2-size: clamp(1rem, 2.5vw, 1.6rem);
  }}
}}
@media (max-height: 600px) {{
  :root {{
    --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
    --content-gap: clamp(0.3rem, 0.9vw, 0.7rem);
    --title-size: clamp(1rem, 3.5vw, 1.9rem);
    --body-size: clamp(0.65rem, 1vw, 0.85rem);
  }}
  .nav-dots, .keyboard-hint {{ display: none; }}
}}
@media (max-height: 500px) {{
  :root {{
    --slide-padding: clamp(0.4rem, 2vw, 1rem);
    --title-size: clamp(0.9rem, 3vw, 1.4rem);
    --h2-size: clamp(0.8rem, 2vw, 1.1rem);
    --body-size: clamp(0.6rem, 0.9vw, 0.78rem);
  }}
}}
@media (prefers-reduced-motion: reduce) {{
  *, *::before, *::after {{ animation-duration: 0.01ms !important; transition-duration: 0.2s !important; }}
  html {{ scroll-behavior: auto; }}
}}

/* === GRID BG PATTERN === */
.grid-bg {{
  background-image:
    linear-gradient(rgba(59,157,221,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(59,157,221,0.04) 1px, transparent 1px);
  background-size: clamp(30px,4vw,60px) clamp(30px,4vw,60px);
}}

/* === GLOW ORBS === */
.orb {{
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
  opacity: 0.45;
}}
.orb-blue {{ background: rgba(59,157,221,0.5); }}
.orb-amber {{ background: rgba(245,166,35,0.4); }}
.orb-teal {{ background: rgba(32,201,186,0.4); }}

/* === SLIDE NUMBER === */
.slide-num {{
  position: absolute;
  top: clamp(0.8rem,2vh,1.6rem);
  left: clamp(1rem,3vw,3rem);
  font-family: var(--font-m);
  font-size: var(--small-size);
  color: var(--text3);
  letter-spacing: 0.08em;
  z-index: 10;
}}

/* === ACCENT TOP BAR === */
.accent-bar {{
  height: 3px;
  background: linear-gradient(90deg, var(--blue), var(--amber), transparent);
  flex-shrink: 0;
}}

/* === REVEAL ANIMATION === */
.reveal {{
  opacity: 0;
  transform: translateY(24px);
  transition: opacity var(--dur) var(--ease), transform var(--dur) var(--ease);
}}
.slide.visible .reveal {{ opacity: 1; transform: translateY(0); }}
.reveal:nth-child(1) {{ transition-delay: 0.05s; }}
.reveal:nth-child(2) {{ transition-delay: 0.15s; }}
.reveal:nth-child(3) {{ transition-delay: 0.25s; }}
.reveal:nth-child(4) {{ transition-delay: 0.35s; }}
.reveal:nth-child(5) {{ transition-delay: 0.45s; }}
.reveal:nth-child(6) {{ transition-delay: 0.55s; }}

.reveal-left {{
  opacity: 0;
  transform: translateX(-32px);
  transition: opacity var(--dur) var(--ease), transform var(--dur) var(--ease);
}}
.slide.visible .reveal-left {{ opacity: 1; transform: translateX(0); }}

.reveal-right {{
  opacity: 0;
  transform: translateX(32px);
  transition: opacity var(--dur) var(--ease), transform var(--dur) var(--ease);
}}
.slide.visible .reveal-right {{ opacity: 1; transform: translateX(0); }}

/* === PROGRESS BAR === */
.progress-bar {{
  position: fixed;
  top: 0; left: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--blue), var(--amber));
  width: 0%;
  z-index: 1000;
  transition: width 0.3s ease;
}}

/* === NAV DOTS === */
.nav-dots {{
  position: fixed;
  right: clamp(0.8rem,2vw,1.5rem);
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 100;
  list-style: none;
}}
.nav-dot {{
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--text3);
  cursor: pointer;
  transition: all 0.3s ease;
  border: none;
  padding: 0;
}}
.nav-dot.active {{
  background: var(--blue);
  box-shadow: 0 0 8px var(--blue-glow);
  transform: scale(1.4);
}}

/* ==========================================
   SLIDE 1 — TITLE SLIDE
   ========================================== */
.title-slide {{
  background: var(--bg);
}}
.title-slide .hero {{
  display: flex;
  flex-direction: column;
  gap: var(--content-gap);
  max-width: min(85vw, 960px);
}}
.title-slide h1 {{
  font-family: var(--font-d);
  font-size: clamp(1.5rem, 4.2vw, 3.5rem);
  font-weight: 800;
  line-height: 1.1;
  color: var(--text);
  letter-spacing: -0.02em;
}}
.title-slide h1 span {{ color: var(--blue); }}
.title-slide .tagline {{
  font-family: var(--font-m);
  font-size: clamp(0.7rem, 1.3vw, 1rem);
  color: var(--amber);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}}
.title-slide .stat-row {{
  display: flex;
  gap: clamp(0.8rem, 2vw, 2rem);
  flex-wrap: wrap;
  margin-top: clamp(0.3rem,1vh,0.8rem);
}}
.stat-chip {{
  display: flex;
  flex-direction: column;
  padding: clamp(0.5rem,1.2vh,0.8rem) clamp(0.8rem,1.5vw,1.2rem);
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
}}
.stat-chip .val {{
  font-family: var(--font-m);
  font-size: clamp(0.9rem, 2vw, 1.5rem);
  font-weight: 600;
  color: var(--blue);
  line-height: 1;
}}
.stat-chip .lbl {{
  font-size: var(--small-size);
  color: var(--text2);
  margin-top: 0.2em;
}}
.title-slide .paper-ref {{
  font-size: var(--small-size);
  color: var(--text3);
  font-family: var(--font-m);
  margin-top: clamp(0.2rem,0.8vh,0.6rem);
  border-top: 1px solid var(--border2);
  padding-top: clamp(0.4rem,1vh,0.7rem);
}}
.title-slide .paper-ref span {{ color: var(--blue); }}

/* ==========================================
   SLIDE 2 — MOTIVATION
   ========================================== */
.motivation-slide .two-col {{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(1rem, 2.5vw, 2.5rem);
  margin-top: var(--content-gap);
}}
.problem-card {{
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: clamp(0.8rem,2vh,1.5rem) clamp(0.8rem,2vw,1.5rem);
}}
.problem-card h3 {{
  font-family: var(--font-d);
  font-size: var(--h3-size);
  font-weight: 700;
  margin-bottom: var(--el-gap);
}}
.problem-card.bad h3 {{ color: var(--red); }}
.problem-card.good h3 {{ color: var(--green); }}
.problem-card ul {{
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: clamp(0.3rem,0.7vh,0.6rem);
}}
.problem-card li {{
  font-size: var(--body-size);
  color: var(--text2);
  padding-left: 1.1em;
  position: relative;
  line-height: 1.4;
}}
.problem-card li::before {{
  content: '→';
  position: absolute;
  left: 0;
  color: var(--text3);
}}
.motivation-slide .solution-bar {{
  margin-top: var(--content-gap);
  background: linear-gradient(135deg, rgba(59,157,221,0.12), rgba(245,166,35,0.08));
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: clamp(0.5rem,1.2vh,1rem) clamp(0.8rem,2vw,1.5rem);
  display: flex;
  align-items: center;
  gap: 1rem;
}}
.solution-bar .label {{
  font-family: var(--font-m);
  font-size: var(--small-size);
  color: var(--amber);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  white-space: nowrap;
}}
.solution-bar p {{
  font-size: var(--body-size);
  color: var(--text);
  line-height: 1.4;
}}

/* ==========================================
   SLIDE 3 — ARCHITECTURE OVERVIEW
   ========================================== */
.arch-slide .arch-layout {{
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  gap: clamp(1rem, 2.5vw, 2.5rem);
  align-items: center;
  margin-top: var(--content-gap);
}}
.arch-slide .arch-text ul {{
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: clamp(0.4rem,1vh,0.8rem);
  margin-top: var(--el-gap);
}}
.arch-slide .arch-text li {{
  font-size: var(--body-size);
  color: var(--text2);
  padding-left: 1.2em;
  position: relative;
  line-height: 1.4;
}}
.arch-slide .arch-text li::before {{
  content: '▸';
  position: absolute;
  left: 0;
  color: var(--blue);
}}
.arch-slide .arch-text li strong {{ color: var(--text); font-weight: 600; }}
.arch-slide .fig-container {{
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
}}
.arch-slide .fig-container img {{
  max-width: 100%;
  max-height: min(55vh, 380px);
  object-fit: contain;
  border-radius: 8px;
}}

/* ==========================================
   SLIDE 4 — MLA MECHANISM
   ========================================== */
.mla-slide .mla-layout {{
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(1rem, 2.5vw, 2.5rem);
  align-items: center;
  margin-top: var(--content-gap);
}}
.mla-slide .fig-container {{
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
}}
.mla-slide .fig-container img {{
  max-width: 100%;
  max-height: min(55vh, 370px);
  object-fit: contain;
  border-radius: 8px;
}}
.mla-slide .mla-points {{
  display: flex;
  flex-direction: column;
  gap: clamp(0.5rem,1.2vh,1rem);
}}
.mla-point {{
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: clamp(0.5rem,1.2vh,0.9rem) clamp(0.7rem,1.5vw,1.1rem);
  border-left: 3px solid var(--blue);
}}
.mla-point.highlight {{ border-left-color: var(--amber); background: var(--amber-dim); }}
.mla-point h4 {{
  font-family: var(--font-d);
  font-size: clamp(0.7rem, 1.1vw, 0.9rem);
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.2em;
}}
.mla-point p {{
  font-size: clamp(0.62rem, 0.95vw, 0.82rem);
  color: var(--text2);
  line-height: 1.4;
}}
.mla-point.highlight h4 {{ color: var(--amber); }}

/* ==========================================
   SLIDE 5 — DEEPSEEKMOE
   ========================================== */
.moe-slide .moe-grid {{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(0.6rem,1.5vw,1.2rem);
  margin-top: var(--content-gap);
}}
.moe-card {{
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: clamp(0.7rem,1.5vh,1.1rem) clamp(0.7rem,1.5vw,1.1rem);
}}
.moe-card h4 {{
  font-family: var(--font-d);
  font-size: clamp(0.75rem, 1.2vw, 1rem);
  font-weight: 700;
  margin-bottom: clamp(0.3rem,0.7vh,0.5rem);
}}
.moe-card.shared h4 {{ color: var(--blue); }}
.moe-card.routed h4 {{ color: var(--amber); }}
.moe-card.routing h4 {{ color: var(--green); }}
.moe-card.balance h4 {{ color: #a78bfa; }}
.moe-card p {{
  font-size: clamp(0.62rem, 0.95vw, 0.82rem);
  color: var(--text2);
  line-height: 1.45;
}}
.moe-card p strong {{ color: var(--text); font-weight: 500; }}
.moe-badge {{
  display: inline-block;
  font-family: var(--font-m);
  font-size: clamp(0.55rem, 0.8vw, 0.7rem);
  padding: 0.15em 0.5em;
  border-radius: 4px;
  margin-bottom: 0.4em;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}}
.moe-card.shared .moe-badge {{ background: rgba(59,157,221,0.2); color: var(--blue); }}
.moe-card.routed .moe-badge {{ background: rgba(245,166,35,0.2); color: var(--amber); }}
.moe-card.routing .moe-badge {{ background: rgba(46,204,113,0.2); color: var(--green); }}
.moe-card.balance .moe-badge {{ background: rgba(167,139,250,0.2); color: #a78bfa; }}
.moe-formula {{
  margin-top: var(--content-gap);
  background: rgba(59,157,221,0.06);
  border: 1px solid var(--border2);
  border-radius: 8px;
  padding: clamp(0.4rem,1vh,0.7rem) clamp(0.8rem,2vw,1.2rem);
  font-family: var(--font-m);
  font-size: clamp(0.6rem, 0.9vw, 0.78rem);
  color: var(--text2);
  text-align: center;
}}
.moe-formula span {{ color: var(--blue); font-weight: 600; }}

/* ==========================================
   SLIDE 6 — EFFICIENCY GAINS
   ========================================== */
.eff-slide .eff-header {{
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: var(--content-gap);
}}
.eff-slide .vs-label {{
  font-family: var(--font-m);
  font-size: var(--small-size);
  color: var(--text3);
  background: var(--card);
  border: 1px solid var(--border2);
  border-radius: 20px;
  padding: 0.25em 0.8em;
  align-self: center;
  white-space: nowrap;
}}
.eff-table {{
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border-radius: 12px;
  overflow: hidden;
}}
.eff-table thead tr {{
  background: var(--bg3);
}}
.eff-table th {{
  font-family: var(--font-m);
  font-size: clamp(0.6rem, 0.85vw, 0.75rem);
  font-weight: 600;
  color: var(--text3);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: clamp(0.5rem,1.2vh,0.8rem) clamp(0.8rem,1.5vw,1.2rem);
  text-align: left;
  border-bottom: 1px solid var(--border);
}}
.eff-table th:last-child {{ color: var(--amber); }}
.eff-table td {{
  font-size: var(--body-size);
  padding: clamp(0.6rem,1.4vh,1rem) clamp(0.8rem,1.5vw,1.2rem);
  border-bottom: 1px solid var(--border2);
  background: var(--card);
  vertical-align: middle;
  line-height: 1.3;
}}
.eff-table tr:last-child td {{ border-bottom: none; }}
.eff-table .metric-name {{
  font-weight: 500;
  color: var(--text);
  font-family: var(--font-b);
}}
.eff-table .val-old {{
  font-family: var(--font-m);
  color: var(--text3);
  font-size: clamp(0.65rem, 1vw, 0.88rem);
}}
.eff-table .val-new {{
  font-family: var(--font-m);
  font-weight: 600;
  font-size: clamp(0.7rem, 1.1vw, 0.95rem);
}}
.eff-table .val-new.green {{ color: var(--green); }}
.eff-table .val-new.amber {{ color: var(--amber); }}
.eff-table .val-new.blue {{ color: var(--blue); }}
.eff-table .delta {{
  display: inline-flex;
  align-items: center;
  gap: 0.3em;
  font-family: var(--font-m);
  font-size: clamp(0.62rem, 0.95vw, 0.82rem);
  font-weight: 600;
  padding: 0.2em 0.55em;
  border-radius: 5px;
}}
.delta.improve {{ background: rgba(46,204,113,0.15); color: var(--green); }}
.delta.big-improve {{ background: rgba(245,166,35,0.15); color: var(--amber); }}

/* ==========================================
   SLIDE 7 — MMLU SCATTER PLOT
   ========================================== */
.mmlu-slide .chart-wrap {{
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  margin-top: clamp(0.3rem,0.8vh,0.7rem);
}}
.mmlu-slide svg {{
  width: 100%;
  max-height: min(62vh, 420px);
  overflow: visible;
}}

/* ==========================================
   SLIDE 8 — ALIGNMENT RESULTS
   ========================================== */
.align-slide .align-layout {{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(1rem,2.5vw,2.5rem);
  align-items: start;
  margin-top: var(--content-gap);
}}
.align-pipeline {{
  display: flex;
  flex-direction: column;
  gap: clamp(0.4rem,1vh,0.7rem);
}}
.pipeline-step {{
  display: flex;
  align-items: flex-start;
  gap: clamp(0.5rem,1vw,0.8rem);
  padding: clamp(0.5rem,1.2vh,0.8rem) clamp(0.6rem,1.2vw,0.9rem);
  background: var(--card);
  border: 1px solid var(--border2);
  border-radius: 8px;
}}
.pipeline-step .step-num {{
  font-family: var(--font-m);
  font-size: clamp(0.6rem, 0.85vw, 0.75rem);
  font-weight: 600;
  color: var(--blue);
  min-width: 2em;
  padding-top: 0.1em;
}}
.pipeline-step .step-body h4 {{
  font-family: var(--font-d);
  font-size: clamp(0.7rem, 1.1vw, 0.9rem);
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.2em;
}}
.pipeline-step .step-body p {{
  font-size: clamp(0.6rem, 0.88vw, 0.78rem);
  color: var(--text2);
  line-height: 1.35;
}}
.bench-scores {{
  display: flex;
  flex-direction: column;
  gap: clamp(0.4rem,1vh,0.7rem);
}}
.bench-score-card {{
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: clamp(0.5rem,1.2vh,0.8rem) clamp(0.7rem,1.5vw,1.1rem);
  display: flex;
  justify-content: space-between;
  align-items: center;
}}
.bench-score-card .bench-name {{
  font-size: clamp(0.62rem, 0.95vw, 0.82rem);
  color: var(--text2);
}}
.bench-score-card .bench-val {{
  font-family: var(--font-m);
  font-size: clamp(0.85rem, 1.5vw, 1.2rem);
  font-weight: 600;
  color: var(--amber);
}}
.align-note {{
  margin-top: var(--el-gap);
